import {read,write,loadChapters,hasTerm} from './data-tools.mjs';
const batch='moderate-hard-1',level='Moderate–Hard';
const targetIds=['cloze','fillers','grammar'];
const chapters=Object.fromEntries(targetIds.map(id=>[id,read('chapters/'+id+'.json')]));
if(Object.values(chapters).some(c=>c.packs.some(p=>p.id.startsWith('MH-'))))throw Error('Moderate–Hard batch already exists; edit reviewed canonical JSON.');
const before=loadChapters().flatMap(({chapter:c})=>c.packs.flatMap(p=>p.questions)).map(q=>({id:q.id,type:q.type,prompt:q.prompt,options:q.options,answer:q.answer,explanation:q.explanation}));
fs.writeFileSync(new URL('../tests/fixtures/pre-moderate-hard-content.json',import.meta.url),JSON.stringify({questionIds:before.map(q=>q.id),questionCount:before.length,sha256:crypto.createHash('sha256').update(JSON.stringify(before)).digest('hex')},null,2)+'\n');
const source={kind:'original-format-practice',formatReferences:[
 'SBI-Clerk-Mains-Memory-Based-2023-2024.pdf: Q51–57, multiple suitable cloze words',
 'IBPS_Clerk_Mains_7_Oct_2023_Memory_Based_Paper_3bb94da0404e140c27c7ba5d41e2a5b6.pdf: Q57–60, combination fillers',
 'Mains Checklist 53, PDF pp2–5: paired fillers and combined grammar',
 'IBPS-Clerk-Mains-Question-Paper-Held-on-13.10.2024.pdf: Q61–67, multiple incorrect parts'
],note:'Original reviewed practice targeting moderate-to-hard reasoning. Source formats inform construction; difficulty is not independently calibrated.'};
let serial=0;
function single(prompt,answer,wrong,clue,rule,model,relationship,skill,review){
 const options=wrong.map(([s])=>s);options.splice(serial++%5,0,answer);
 return {type:'single',prompt,instructions:'Choose the BEST completion using the full context. Check degree, scope, meaning and grammatical fit.',options,answer,skill,batch,source,vocabulary:[],explanation:{clue,rule,model,relationship,rejects:wrong.map(([option,reason])=>({option,reason}))},difficultyReview:{target:level,nearestAlternative:review[0],whyNot:review[1],reasoningSteps:review.slice(2)}};
}
function combination(prompt,candidates,answer,options,clue,rule,model,skill,review,direction='correct'){
 return {type:'multiple',prompt,instructions:`Evaluate every candidate independently and choose ALL and ONLY the ${direction==='incorrect'?'incorrect':'valid'} ones.`,options,answer,candidates,selectionDirection:direction,skill,batch,source,vocabulary:[],explanation:{relationship:direction==='incorrect'?'Direction: select all INCORRECT statements':'Multiple-fit direction: more than one candidate may be valid',clue,rule,model},difficultyReview:{target:level,nearestAlternative:review[0],whyNot:review[1],reasoningSteps:review.slice(2)}};
}
function clozePack(id,title,passage,rows){
 const p={id,title,level,passage,batch,questions:rows.map((r,i)=>{
  const q=r.candidates?combination('Blank '+(i+1),r.candidates,r.answer,r.options,r.clue,r.rule,r.model,'multiple-fit cloze',r.review):single('Blank '+(i+1),r.answer,r.wrong,r.clue,r.rule,r.model,r.relationship||'Contextual scope, evidence and degree','word/phrase cloze',r.review);
  q.id='cloze/'+id+'-Q'+(i+1);q.slot=i+1;q.completion=r.completion||r.answer;q.instructions=q.candidates?'Select every candidate that fits the blank in the full passage.':'Choose the BEST word or phrase in the full passage; a nearby meaning is not automatically interchangeable.';return q;
 })};chapters.cloze.packs.push(p);
}
